    const knowledge = [["تركيب الذره|بروتون|نيوترون|الكترون|العدد الذري|العدد الكتلي", "تتكون الذرة من نواة فيها بروتونات موجبة ونيوترونات متعادلة، وتوجد الإلكترونات السالبة في مستويات طاقة حول النواة. العدد الذري يساوي عدد البروتونات ويحدد العنصر، والعدد الكتلي يساوي البروتونات + النيوترونات. الذرة المتعادلة عدد إلكتروناتها يساوي عدد بروتوناتها؛ وإذا فقدت إلكترونات أو اكتسبتها تكوّن أيونًا."], ["التوزيع الالكتروني|الافلاك|مستويات الطاقه|قاعدة اوفباو", "يُكتب التوزيع الإلكتروني بترتيب امتلاء المستويات الفرعية مثل 1s² 2s² 2p⁶ 3s² 3p⁶. يتسع المستوى الفرعي s لإلكترونين وp لستة وd لعشرة وf لأربعة عشر. عند كتابة التوزيع يجب مراعاة ترتيب الامتلاء وقواعد باولي وهوند، والانتباه إلى الاستثناءات المعروفة لبعض العناصر الانتقالية."], ["نظائر|نظير|الكتله الذريه النسبيه", "النظائر ذرات للعنصر نفسه لها عدد البروتونات نفسه، لكنها تختلف في عدد النيوترونات؛ لذا تختلف أعدادها الكتلية. الكتلة الذرية النسبية في الجدول الدوري متوسط مرجّح لكتل النظائر بحسب وفرتها الطبيعية، ولذلك لا تكون عددًا صحيحًا غالبًا."], ["الجدول الدوري|نصف القطر الذري|طاقه التاين|السالبيه الكهربائيه|الكهروسالبيه", "عبر الدورة من اليسار إلى اليمين يقل نصف القطر الذري عمومًا بسبب ازدياد الشحنة النووية الفعالة. نزولًا في المجموعة يزداد نصف القطر غالبًا لإضافة مستويات طاقة. تميل طاقة التأين والسالبية الكهربائية إلى الازدياد عبر الدورة والانخفاض نزولًا في المجموعة، مع وجود استثناءات بنيوية."], ["الرابطه الايونيه|الرابطه التساهميه|الرابطه الفلزيه|قطبيه الجزيء", "في الرابطة الأيونية تتجاذب أيونات موجبة وسالبة بعد انتقال إلكترونات غالبًا. في التساهمية تتشارك الذرات أزواجًا إلكترونية، وقد تكون الرابطة قطبية بحسب فرق السالبية. في الفلزات تتحرك إلكترونات التكافؤ بين الأيونات الفلزية، وهذا يفسر التوصيل وقابلية الطرق والسحب."], ["مول|عدد افوجادرو|ثابت افوجادرو|الكتله الموليه", "المول يحتوي على نحو 6.022×10²³ كيانًا. عدد المولات n = الكتلة m ÷ الكتلة المولية M. إذا كانت الكتلة بالغرام والكتلة المولية بالغرام/مول، تكون كمية المادة بالمول. تأكد من صيغة المادة وعدّ الذرات أو الأيونات المطلوبة في السؤال."], ["مولاريه|التركيز المولاري|تخفيف محلول|معادله التخفيف", "المولارية M = عدد مولات المذاب ÷ حجم المحلول باللتر. عند التخفيف بإضافة المذيب مع بقاء كمية المذاب ثابتة نستخدم M₁V₁ = M₂V₂. يجب استخدام وحدات حجم متوافقة في طرفي المعادلة، وغالبًا اللتر أو الملليلتر للطرفين."], ["الغاز المثالي|قانون بويل|قانون شارل|جاي لوساك|pv=nrt", "للغاز المثالي PV=nRT مع استخدام درجة الحرارة بالكلفن ووحدات متوافقة مع ثابت الغاز. قانون بويل: P₁V₁=P₂V₂ عند ثبات الحرارة وكمية الغاز. قانون شارل: V₁/T₁=V₂/T₂ عند ثبات الضغط. قانون جاي لوساك: P₁/T₁=P₂/T₂ عند ثبات الحجم."], ["قانون دالتون|الضغط الجزئي|ضغط بخار الماء", "ضغط الغاز الكلي في خليط مثالي يساوي مجموع الضغوط الجزئية: Pالكلي = مجموع Pᵢ. ويُحسب ضغط الغاز الجاف فوق الماء بطرح ضغط بخار الماء من الضغط المقاس الكلي، إذا جُمعت البيانات وفق شروط التجربة المعتادة."], ["سرعه التفاعل|العامل الحفاز|طاقه التنشيط|نظريه التصادم", "تزداد سرعة التفاعل غالبًا بزيادة درجة الحرارة أو التركيز أو مساحة سطح المادة الصلبة، لأن نسبة التصادمات الفعالة تزداد. العامل الحفاز يوفر مسارًا أقل في طاقة التنشيط ويزيد سرعتي التفاعل الأمامي والعكسي دون تغيير ثابت الاتزان."], ["اتزان كيميائي|ثابت الاتزان|مبدا لوشاتيليه|لو شاتيليه", "عند الاتزان الديناميكي تتساوى سرعتا التفاعل الأمامي والعكسي، وتبقى التراكيز ثابتة ظاهريًا. يغيّر التركيز أو الضغط أو الحرارة موضع الاتزان وفق الظروف، لكن العامل الحفاز لا يغيّر قيمة ثابت الاتزان؛ بل يسرّع الوصول إليه. الحرارة وحدها تغيّر ثابت الاتزان بحسب كون التفاعل ماصًا أو طاردًا."], ["حمض قوي|قاعده قويه|حمض ضعيف|قاعده ضعيفه|التاين", "الحمض القوي يتأين بدرجة كبيرة جدًا في الماء، والضعيف يتأين جزئيًا ويكوّن اتزانًا. القوة تختلف عن التركيز؛ فقد يكون الحمض قويًا مخففًا أو ضعيفًا مركزًا. لحساب pH يلزم تحديد نوع المادة وتركيزها، وقد نحتاج ثابت التأين للمواد الضعيفة."], ["رقم هيدروجيني|حساب ph|مقياس الحموضه|هيدرونيوم", "pH = −log₁₀[H₃O⁺]. عند 25°C يكون الوسط الحمضي أقل من 7، والقاعدي أعلى من 7، والمتعادل قريبًا من 7. انخفاض pH بمقدار وحدة واحدة يعني أن تركيز الهيدرونيوم ازداد عشرة أضعاف. لا تخلط بين قوة الحمض وتركيزه."], ["محلول منظم|بافر|المحلول المنظم", "المحلول المنظم يقاوم تغير pH عند إضافة كميات صغيرة من حمض أو قاعدة، ويتكون عادة من حمض ضعيف وقاعدته المرافقة أو قاعدة ضعيفة وحمضها المرافق. تنخفض فعاليته عندما تُستهلك كمية كبيرة من أحد المكونين أو تتجاوز الإضافة سعته التنظيمية."], ["حاصل الاذابه|ksp|ذوبانيه|راسب|ترسيب", "يمكن توقع الترسيب بمقارنة حاصل الأيونات Q مع ثابت حاصل الإذابة Ksp: إذا كان Q أكبر من Ksp يصبح الترسيب ممكنًا حتى يعود النظام إلى الاتزان. إذا كان Q أصغر من Ksp فالمحلول غير مشبع في النموذج المعتاد. تُكتب تعبيرات Ksp من تراكيز الأيونات مرفوعة إلى معاملات المعادلة الموزونة."], ["اكسده واختزال|عدد التاكسد|عامل مؤكسد|عامل مختزل", "الأكسدة هي فقد الإلكترونات أو ازدياد عدد التأكسد، والاختزال هو اكتساب الإلكترونات أو انخفاض عدد التأكسد. العامل المؤكسد يكتسب إلكترونات ويُختزل، أما العامل المختزل فيفقد إلكترونات ويُؤكسد. عند موازنة المعادلات الأيونية نراعي حفظ الذرات والشحنة."], ["خلية جلفانيه|خلية فولتية|تحليل كهربائي|المصعد|المهبط", "الأكسدة تحدث عند المصعد والاختزال عند المهبط في جميع الخلايا. الخلية الجلفانية تنتج كهرباء من تفاعل تلقائي، أما خلية التحليل الكهربائي فتستهلك الكهرباء لدفع تفاعل غير تلقائي. لا تعيّن إشارة القطب اعتمادًا على اسمه فقط؛ حدّد نوع الخلية أولًا."], ["هيدروكربون|الكان|الالكين|الكاين|روابط مزدوجه|روابط ثلاثيه", "الألكانات هيدروكربونات مشبعة بروابط أحادية، والألكينات تحتوي على رابطة مزدوجة واحدة على الأقل، والألكاينات تحتوي رابطة ثلاثية واحدة على الأقل. وجود رابطة π في الألكينات والألكاينات يجعلها أكثر قابلية لتفاعلات الإضافة من الألكانات في ظروف شائعة. تحقق من الصيغة العامة ونوع السلسلة قبل تسمية المركب."], ["كحول|مجموعة الهيدروكسيل|الدهيد|كيتون|حمض كربوكسيلي|استر", "تحتوي الكحولات على مجموعة هيدروكسيل مرتبطة بذرة كربون مشبعة. الألدهيد يحتوي مجموعة –CHO طرفية، والكيتون مجموعة كربونيل داخل السلسلة غالبًا. الأحماض الكربوكسيلية تحتوي –COOH، والإسترات تحتوي –COO– بين مجموعتين عضويتين وتنتج عادة من تفاعل حمض كربوكسيلي مع كحول."], ["تولينز|فهلنج|اليود والنشا|ماء البروم|اختبار الغذاء", "في اختبار تولينز الموجب للألدهيد قد تتكون مرآة فضية، بينما يعطي فهلنج مع ألدهيد مختزل راسبًا أحمر آجريًا. اليود يكشف النشا بتغير إلى أزرق مسود. ماء البروم يزول لونه عادة مع مركبات غير مشبعة في شروط الاختبار. يجب تفسير النتيجة حسب الكاشف المستعمل، لا حسب اللون وحده."], ["قوى بين جزيئيه|روابط هيدروجينيه|قوى لندن|قوى ثنائي القطب", "قوى التجاذب بين الجزيئات أضعف عادة من الروابط داخل الجزيء. الرابطة الهيدروجينية تظهر عندما يرتبط H بـN أو O أو F ويتجاذب مع زوج إلكتروني مناسب في جزيء آخر. قوى لندن موجودة بين جميع الجسيمات وتزداد عادة مع قابلية الاستقطاب وعدد الإلكترونات ومساحة التلامس."], ["خاصيه تجميعيه|الضغط الاسموزي|ارتفاع درجه الغليان|انخفاض درجه التجمد|خفض درجه التجمد", "الخواص التجميعية للمحاليل المخففة تعتمد على عدد جسيمات المذاب الفعالة: انخفاض ضغط البخار، وارتفاع درجة الغليان، وانخفاض التجمد، والضغط الأسموزي. يزداد الأثر مع التركيز الفعلي للجسيمات؛ وقد يؤثر التأين ومعامل فانتهوف وعدم مثالية المحلول في الحسابات."], ["قانون نيوتن|قصور ذاتي|القوه المحصله|قانون نيوتن الثاني", "القانون الأول لنيوتن يصف القصور الذاتي: يبقى الجسم ساكنًا أو يتحرك بسرعة ثابتة في خط مستقيم إذا كانت محصلة القوى صفرًا. القانون الثاني: محصلة القوة = الكتلة × التسارع. القانون الثالث: لكل فعل رد فعل مساوٍ له مقدارًا ومعاكس اتجاهًا، وهما يؤثران في جسمين مختلفين."], ["السرعه|التسارع|الحركه بعجله|معادلات الحركه", "السرعة المتوسطة = الإزاحة ÷ الزمن، بينما السرعة القياسية المتوسطة = المسافة ÷ الزمن. التسارع = التغير في السرعة ÷ الزمن. عند تسارع ثابت يمكن استخدام v=v₀+at و Δx=v₀t+½at² و v²=v₀²+2aΔx، مع توحيد الوحدات والإشارات والاتجاه."], ["قذف|المقذوفات|مدى افقي|زاويه الاطلاق", "في نموذج المقذوفات دون مقاومة الهواء، تكون الحركة الأفقية بسرعة ثابتة والحركة الرأسية بتسارع g نحو الأسفل. عند الإطلاق والهبوط على المستوى نفسه يكون المدى R=v₀² sin(2θ)/g، ويبلغ أقصاه عند زاوية 45° إذا ثُبتت السرعة وكان الإطلاق والهبوط على الارتفاع نفسه."], ["شغل|قدره|طاقه حركيه|طاقه وضع|حفظ الطاقه", "الشغل في حالة قوة ثابتة موازية للإزاحة W=Fd، وإذا كانت بزاوية فـ W=Fd cosθ. القدرة P=W/t. الطاقة الحركية Ek=½mv² وطاقة الوضع الثقالية قرب سطح الأرض Ug=mgh. تتحول الطاقة بين صورها وتبقى محفوظة في نظام معزول؛ أما الاحتكاك فيحوّل جزءًا من الطاقة الميكانيكية إلى طاقة داخلية."], ["زخم|كمية الحركه|دفع|تصادم", "الزخم p=mv، والدفع J=FΔt ويساوي التغير في الزخم عندما تُستخدم القوة المحصلة على الفترة. في نظام معزول يكون الزخم الكلي محفوظًا قبل التصادم وبعده. التصادم المرن يحفظ الطاقة الحركية الكلية أيضًا، بينما غير المرن لا يحفظها بالضرورة."], ["حركه دائريه|قوه مركزيه|تسارع مركزي", "في الحركة الدائرية المنتظمة يكون مقدار السرعة ثابتًا لكن اتجاهها يتغير، لذلك يوجد تسارع مركزي نحو المركز a_c=v²/r. القوة المحصلة المركزية F_c=mv²/r. ليست القوة المركزية نوعًا مستقلًا؛ قد يوفرها الشد أو الاحتكاك أو الجاذبية بحسب النظام."], ["جاذبيه|قانون الجذب العام|المدارات", "قوة الجذب بين كتلتين تتناسب طرديًا مع حاصل ضرب الكتلتين وعكسيًا مع مربع المسافة بين مركزيهما: F=Gm₁m₂/r². وزن الجسم قرب سطح الأرض W=mg. تتغير قيمة g بين الكواكب، فيتغير الوزن، لكن كتلة الجسم تبقى نفسها ما لم يتغير مقدار مادته."], ["الكثافه|قوه الطفو|يطفو|يغرق|مبدا ارخميدس", "الكثافة ρ=m/V. تؤثر قوة الطفو إلى أعلى وتساوي وزن المائع المزاح وفق مبدأ أرخميدس. يطفو الجسم في الاتزان إذا أمكن لقوة الطفو موازنة وزنه؛ وعند الطفو الحر تكون كثافته المتوسطة أقل من كثافة السائل غالبًا. لا يكفي شكل الجسم وحده للحكم على الطفو."], ["ضغط السائل|الضغط الهيدروستاتيكي|ضغط|عمق السائل", "الضغط P=F/A، ووحدة الضغط في النظام الدولي الباسكال. في سائل ساكن كثافته ρ وعلى عمق h يكون فرق الضغط الهيدروستاتيكي ΔP=ρgh، لذلك يزداد الضغط مع العمق والكثافة وتسارع الجاذبية. الضغط الكلي يتضمن أيضًا الضغط الواقع على سطح السائل."], ["حراره نوعيه|سعرات|حراره التفاعل|تغير درجه الحراره|السعه الحراريه", "الحرارة المنتقلة دون تغير طور تُحسب غالبًا من Q=mcΔT، حيث m الكتلة وc الحرارة النوعية وΔT التغير في درجة الحرارة. إذا تغير الطور تُستخدم الحرارة الكامنة Q=mL. في المسائل الحرارية راعِ إشارة الطاقة وما إذا كان الجسم يكتسب حرارة أو يفقدها، وميّز بين درجة الحرارة والطاقة الحرارية."], ["تبخر|غليان|ضغط بخار|درجه الغليان", "التبخر يحدث عند سطح السائل ويمكن أن يحدث دون بلوغ درجة الغليان، أما الغليان فيحدث عندما يصبح ضغط بخار السائل مساويًا للضغط الخارجي. لذلك تنخفض درجة الغليان عند خفض الضغط الخارجي وترتفع عند زيادته. تؤثر القوى بين الجزيئات في ضغط البخار ودرجة الغليان أيضًا."], ["موجه|التردد|الطول الموجي|سرعه الموجه", "العلاقة الأساسية للموجة v=fλ، حيث v سرعة الانتشار وf التردد وλ الطول الموجي. عند انتقال موجة إلى وسط آخر قد تتغير سرعتها وطولها الموجي، بينما يبقى ترددها محددًا بالمصدر عادة. السعة ترتبط بمقدار الاضطراب والطاقة المنقولة في كثير من النماذج."], ["صوت|حده الصوت|شده الصوت|ديسيبل", "حدة الصوت ترتبط بالتردد: تردد أعلى يعني صوتًا أرفع. شدة الصوت ترتبط بسعة الاهتزاز والطاقة التي تحملها الموجة. الصوت موجة ميكانيكية تحتاج وسطًا ماديًا ولا تنتقل في الفراغ. الديسيبل مقياس لوغاريتمي لمستوى الشدة، لذلك لا تُقارن قيمه كأنها فروق خطية بسيطة."], ["انعكاس الضوء|انكسار الضوء|قانون سنيل|زاويه حرجه", "في الانعكاس زاوية السقوط تساوي زاوية الانعكاس وتقاسان من العمود المقام. في الانكسار n₁ sinθ₁=n₂ sinθ₂. عند انتقال الضوء إلى وسط أعلى معامل انكسار ينحني نحو العمود، وعند انتقاله إلى وسط أقل معاملًا قد يحدث انعكاس كلي داخلي إذا تجاوزت زاوية السقوط الزاوية الحرجة."], ["عدسه محدبه|عدسه مقعره|العدسات|معادله العدسه|بعد بؤري", "العدسة المحدبة مجمعة للأشعة المتوازية غالبًا، والمقعرة مفرقة لها. للعدسة الرقيقة وفق اصطلاح الإشارات المستخدم: 1/f=1/dₒ+1/dᵢ، والتكبير m=−dᵢ/dₒ. ينبغي تحديد اصطلاح الإشارات ومكان الجسم قبل تقرير طبيعة الصورة واتجاهها وحجمها."], ["قانون اوم|مقاومه|تيار كهربائي|فرق الجهد", "قانون أوم V=IR للعناصر الأومية عند ثبات الظروف الفيزيائية المناسبة. القدرة الكهربائية P=VI، ويمكن استخدام P=I²R أو P=V²/R. في التوصيل على التوالي تتساوى شدة التيار وتجمع المقاومات، وفي التوازي يتساوى فرق الجهد وتُجمع مقلوبات المقاومات."], ["مغناطيس|مجال مغناطيسي|الحث الكهرومغناطيسي|قانون فاراداي|لنز", "يتولد جهد حثي عندما يتغير التدفق المغناطيسي خلال دائرة. وفق قانون فاراداي يتناسب مقدار الجهد الحثي مع معدل تغير التدفق وعدد اللفات، واتجاهه وفق قانون لنز يعارض التغير في التدفق الذي سببه. زيادة سرعة الحركة أو عدد اللفات تزيد الجهد الحثي في ظروف مماثلة."], ["قانون كولوم|مجال كهربائي|شحنه كهربائيه|جهد كهربائي", "قوة كولوم بين شحنتين نقطيتين تتناسب مع حاصل ضرب مقدار الشحنتين وعكسيًا مع مربع المسافة. اتجاه القوة يكون تجاذبًا للشحنتين المختلفتين وتنافرًا للمتشابهتين. المجال الكهربائي E=F/q₀، وهو يصف القوة لكل وحدة شحنة اختبار موجبة، والجهد يرتبط بطاقة الوضع لكل وحدة شحنة."], ["عضيات الخليه|الميتوكوندريا|البلاستيده الخضراء|النواه|الغشاء الخلوي|جدار خلوي", "الغشاء الخلوي ينظم مرور المواد، والنواة تحتوي معظم المادة الوراثية في الخلايا حقيقية النواة، والميتوكندريا موقع رئيسي للتنفس الخلوي. البلاستيدات الخضراء في النباتات تقوم بالبناء الضوئي، والجدار الخلوي يوفر الدعم في النبات. تختلف الخلايا النباتية والحيوانية في بعض البنى والوظائف."], ["انتشار|اسموزيه|التناضح|غشاء شبه منفذ", "الانتشار انتقال صافٍ للجسيمات من تركيز أعلى إلى تركيز أقل بفعل الحركة العشوائية. الأسموزية هي انتقال الماء عبر غشاء شبه منفذ نحو الجهة ذات تركيز أعلى من المواد المذابة غير النافذة في النموذج المعتاد. اتجاه الأسموزية يعتمد على فرق الجهد المائي أو التركيز الفعال لا على حجم الخلية فقط."], ["انقسام متساوي|انقسام منصف|الكروموسومات|مراحل الانقسام", "الانقسام المتساوي ينتج عادة خليتين بنتين متقاربتين وراثيًا ويسهم في النمو وتعويض الخلايا. الانقسام المنصف يخفض عدد الكروموسومات إلى النصف لتكوين خلايا تناسلية في الكائنات التي تستخدمه، ويسهم العبور والتوزيع المستقل في التنوع الوراثي."], ["dna|rna|نسخ|ترجمه البروتين|شفرة وراثيه", "يُنسخ جزء من المعلومات الوراثية من DNA إلى RNA، ثم تُترجم شيفرة mRNA على الريبوسوم إلى تسلسل أحماض أمينية في البروتين. يتطلب تفسير الشفرة قراءة الكودونات واتجاه القراءة ومعرفة دور tRNA والريبوسوم. لا تُحوّل كل طفرة بالضرورة إلى تغير في البروتين؛ فقد تكون صامتة أو تؤثر في وظيفته."], ["وراثه مندليه|مربع بانيت|صفة سائده|صفة متنحيه|جينات|اليل", "في تهجين Aa×Aa مع سيادة تامة وانفصال أليلات مندلي وعدم وجود ارتباط تكون النسبة الجينية المتوقعة 1 AA : 2 Aa : 1 aa، والنمط الظاهري 3:1. تتغير النسب عند السيادة غير التامة أو تعدد الأليلات أو الارتباط الجيني أو اختلاف النفوذية. احرص على تعريف الرموز قبل بناء مربع بانيت."], ["بناء ضوئي|تمثيل ضوئي|اليخضور|كلوروفيل", "في البناء الضوئي تمتص الأصباغ الضوئية الطاقة وتُستخدم التفاعلات الضوئية لإنتاج ATP وNADPH ويُطلق الأكسجين من الماء. تستخدم دورة كالفن الطاقة لتثبيت CO₂ وتكوين مركبات عضوية. يتأثر المعدل بالضوء وثاني أكسيد الكربون والحرارة والماء، ويُحدده العامل الأقل ملاءمة ضمن الظروف المدروسة."], ["تنفس خلوي|atp|دوره كربس|سلسله نقل الالكترون", "التنفس الخلوي ينقل الطاقة الكيميائية من الغذاء إلى ATP عبر التحلل السكري ومراحل لاحقة تشمل دورة كربس وسلسلة نقل الإلكترونات في التنفس الهوائي. الأكسجين هو المستقبل النهائي للإلكترونات في السلسلة الهوائية. مقدار ATP الناتج يختلف بحسب الكائن والظروف ومسار الحساب المعتمد."], ["(^|[^ء-ي])(?:فصيله الدم|فصائل الدم|abo|عامل rh|الدوره الدمويه|الدم|دم)(?=$|[^ء-ي])", "تتحدد فصائل ABO بمستضدات على سطح كريات الدم الحمراء وأجسام مضادة في البلازما. عامل Rh يتعلق بمستضدات أخرى منها D. توافق نقل الدم يعتمد على نوع المكوّن المنقول وفحوص المطابقة؛ لا يكفي الاعتماد على قاعدة عامة دون اختبار بنك الدم. يدفع القلب الدم عبر الدورة الرئوية والجهازية."], ["مناعه|اجسام مضاده|خلية b|خلية t|لقاح|ممرض", "المناعة الفطرية استجابة سريعة عامة، أما المناعة التكيفية فتستخدم خلايا B والأجسام المضادة وخلايا T وتكوّن ذاكرة مناعية. اللقاحات تعرض الجهاز المناعي لمستضد أو تعليماته بطريقة تهدف إلى بناء حماية دون إحداث المرض المستهدف بالكيفية نفسها. الأجسام المضادة ترتبط بمستضدات محددة ولا تقتل كل الممرضات وحدها."], ["انزيم|هضم|معدل الانزيم|الموقع النشط", "الإنزيم محفز حيوي يخفض طاقة التنشيط دون أن يُستهلك كليًا. ترتبط كفاءته بدرجة الحرارة وpH وتركيز الركيزة، وقد ينخفض النشاط عند الظروف التي تغير بنيته. للموقع النشط خصائص بنيوية وكيميائية تؤثر في التخصص، وتصل سرعة التفاعل إلى حد أقصى عند تشبع الإنزيم بالركيزة."], ["نظام بيئي|سلسله غذائيه|شبكه غذائيه|منتج|مستهلك|مفترس|فريسه", "النظام البيئي يتضمن الكائنات الحية والعوامل غير الحية وتفاعلاتها. تنتقل الطاقة عبر المستويات الغذائية ويتبدد جزء كبير منها كحرارة، لذلك تقل الطاقة المتاحة عادة في المستويات الأعلى. إزالة نوع أو زيادة أعداده قد تؤثر في أنواع أخرى عبر علاقات الافتراس والتنافس وتوافر الموارد."], ["دوره الماء|تبخر|تكاثف|هطول", "تدفع الطاقة الشمسية التبخر، ثم يبرد بخار الماء ويتكاثف عند ظروف مناسبة لتكوين السحب، ويعود الماء بالهطول. يتحكم فرق الحرارة والرطوبة وحركة الهواء والتضاريس في تكوين السحب والهطول، ثم يتسرب بعض الماء إلى التربة أو يجري إلى الأنهار والبحار."], ["صفائح تكتونيه|زلازل|براكين|موجات زلزاليه", "تتحرك الصفائح التكتونية ببطء فوق الغلاف الموري؛ ويسهم تفاعلها عند الحدود المتباعدة والمتقاربة والانزلاقية في الزلازل والبراكين وتكوين الجبال. تصل موجات P عادة قبل موجات S لأنها أسرع، وموجات S لا تنتقل في السوائل في النموذج المرن المعتاد؛ تُستخدم أزمنة الوصول لتقدير موقع المركز السطحي."], ["طقس|مناخ|احتباس حراري|تغير مناخي|غازات الدفيئه", "الطقس يصف الحالة قصيرة الأمد للغلاف الجوي، بينما المناخ إحصاءات الأنماط على فترات طويلة. غازات الدفيئة تمتص وتعيد إصدار الأشعة تحت الحمراء، ويسهم ازدياد تركيزها بفعل الأنشطة البشرية في رفع متوسط حرارة النظام المناخي وتغيّر أنماط الهطول والبحار والمخاطر المتطرفة."], ["اطوار القمر|خسوف|كسوف|الفصول|ميل محور الارض", "أطوار القمر تنتج من تغير الجزء المضاء الذي نراه خلال دورانه حول الأرض. الكسوف يحدث عندما يقع القمر بين الشمس والأرض على استقامة مناسبة، والخسوف عندما تقع الأرض بين الشمس والقمر. تعاقب الفصول سببه الأساسي ميل محور الأرض مع دورانها حول الشمس، لا المسافة وحدها."], ["كوكب|مدار|النظام الشمسي|جاذبيه الشمس|السنه الضوئيه|نجوم", "تتحرك الكواكب في مدارات بفعل الجاذبية، ويعتمد زمن الدورة المدارية على كتلة الجسم المركزي وبُعد المدار وفق قوانين كبلر. السنة الضوئية وحدة مسافة: المسافة التي يقطعها الضوء في سنة، وليست وحدة زمن. تبدو النجوم مختلفة في اللون واللمعان بسبب درجات حرارتها وأحجامها ومسافاتها ولمعانها الحقيقي."], ["متغير مستقل|متغير تابع|متغيرات ثابته|فرضيه|استقصاء علمي", "في الاستقصاء العلمي المتغير المستقل هو ما يغيّره الباحث عمدًا، والتابع ما يقيس أثر التغيير فيه، والمتغيرات المضبوطة هي العوامل التي يحافظ عليها ثابتة قدر الإمكان. كرر القياسات، استخدم مجموعة مقارنة عندما يلزم، وسجّل وحدات القياس وطريقة جمع البيانات لتمييز العلاقة عن السببية."], ["دقه القياس|الضبط|خطا عشوائي|خطا منتظم|رسم بياني|منحنى", "الدقة تشير إلى قرب القياس من القيمة المرجعية، والتكرارية أو الضبط إلى تقارب القياسات بعضها من بعض. الخطأ العشوائي يسبب تشتتًا، أما الخطأ المنتظم فيزيح النتائج باتجاه أو مقدار متكرر. في الرسم البياني ضع المتغير المستقل غالبًا على المحور الأفقي والتابع على الرأسي، واكتب اسم كل محور ووحدته."], ["لوغاريتم|صيغه علميه|الارقام المعنويه|تحويل الوحدات", "في الصيغة العلمية يكتب العدد a×10ⁿ حيث 1≤|a|<10. اللوغاريتم العشري log(x) هو الأس الذي نرفع إليه 10 للحصول على x، لذلك log(10ⁿ)=n. عند الحسابات العلمية، وحّد الوحدات أولًا واحتفظ بالأرقام الحارسة أثناء الحساب ثم قرّب النتيجة وفق دقة المعطيات والأداة."]];
    knowledge.unshift(...[["انشطار نووي|الانشطار النووي|انشطار اليورانيوم|انشطار النواه|الانشطار والاندماج", "الانشطار النووي هو انقسام نواة ثقيلة إلى نواتين أو أكثر أصغر مع انطلاق طاقة ونيوترونات. قد تُحدث النيوترونات انشطارات إضافية فتتكون سلسلة تفاعل. لا تخلط بين الانشطار والاندماج؛ الانشطار يقسم نواة ثقيلة."], ["اندماج نووي|الاندماج النووي|اندماج الشمس|اندماج الهيدروجين|الاندماج والانشطار", "الاندماج النووي هو اتحاد نوى خفيفة لتكوين نواة أثقل، مع انطلاق طاقة عندما تكون نواتج التفاعل أعلى ترابطًا نوويًا. تعمل النجوم باندماج أنوية الهيدروجين عبر سلسلة تفاعلات، ويحتاج الاندماج على الأرض إلى شروط شديدة من الحرارة والحصر."], ["فرق.*انشطار.*اندماج|انشطار.*اندماج|الفرق بين الانشطار والاندماج", "الانشطار: تنقسم نواة ثقيلة إلى نوى أصغر، مثل بعض تفاعلات اليورانيوم. الاندماج: تتحد نوى خفيفة لتكوين نواة أثقل، كما يحدث في النجوم. كلاهما قد يحرر طاقة بسبب فرق طاقة الربط النووي، لكن ظروف بدء التفاعل ونواتجه ومخلفات التفاعل تختلف."], ["عمر النصف|نصف العمر|النشاط الاشعاعي|تحلل اشعاعي|نظير مشع", "عمر النصف هو الزمن اللازم لانخفاض عدد النوى المشعة غير المتحللة إلى نصف قيمته. بعد n أعمار نصف، تبقى نسبة (1/2)^n من الكمية الأصلية. التحلل احتمالي للنواة المفردة، لكن سلوك عدد كبير من النوى يتبع قانونًا أسيًا."], ["التوزيع الالكتروني|التوزيع الإلكتروني|ترتيب الالكترونات|ترتيب الإلكترونات|مستويات الطاقة", "يُكتب التوزيع الإلكتروني في سطر واحد بترتيب المدارات مثل 1s² 2s² 2p⁶، وتُكتب أعداد الإلكترونات أسسًا علوية. للذرة المتعادلة يساوي مجموع الإلكترونات العدد الذري. تُملأ المدارات وفق ترتيب الطاقة مع مراعاة مبدأ أوفباو وباولي وقاعدة هوند، مع وجود استثناءات معروفة لبعض العناصر الانتقالية."], ["عدد ذري|العدد الذري|عدد البروتونات", "العدد الذري Z هو عدد البروتونات في نواة الذرة، وهو الذي يحدد هوية العنصر. الذرة المتعادلة لها العدد نفسه من الإلكترونات، أما الأيون فقد يختلف عدد إلكتروناته عن عدد بروتوناته."], ["عدد كتلي|العدد الكتلي|النظائر|نظير", "العدد الكتلي A يساوي مجموع البروتونات والنيوترونات في النواة: A = Z + N. نظائر العنصر لها العدد الذري نفسه وعدد نيوترونات مختلف، لذلك تختلف أعدادها الكتلية ولا تتغير هوية العنصر."], ["ترند.*دوري|الجدول الدوري|نصف القطر الذري|طاقة التأين|السالبية الكهربائية", "تتغير الخواص الدورية بسبب الشحنة النووية الفعالة والحجب وبعد إلكترونات التكافؤ. عمومًا يقل نصف القطر عبر الدورة ويزداد نزولًا في المجموعة، بينما تميل طاقة التأين والسالبية الكهربائية إلى الزيادة عبر الدورة والانخفاض نزولًا، مع استثناءات مرتبطة بالبنية الإلكترونية."], ["الروابط الايونية|الرابطة الايونية|الرابطة الأيونية|الرابطة التساهمية|الروابط التساهمية", "الرابطة الأيونية تنشأ من التجاذب الكهروستاتيكي بين أيونات موجبة وسالبة بعد انتقال إلكترونات غالبًا، أما الرابطة التساهمية فتنشأ من مشاركة أزواج إلكترونية بين الذرات. لا يكفي اختلاف السالبية وحده لتصنيف كل رابطة دون مراعاة بنية المادة وسياقها."], ["ph|الرقم الهيدروجيني|مقياس الحموضة|حمض قوي|قاعدة قوية", "في المحاليل المائية المخففة قرب 25°C، يُعرّف pH بأنه −log₁₀(aH⁺) ويُقارب −log₁₀[H₃O⁺] عندما تكون معاملات النشاط قريبة من الواحد. انخفاض pH يعني زيادة نشاط أيونات الهيدرونيوم؛ قوة الحمض تتعلق بالتأين، أما الحموضة الفعلية فتعتمد كذلك على التركيز."], ["المحلول المنظم|البفر|منظم ph|buffer", "المحلول المنظّم يقاوم تغير pH عند إضافة كميات صغيرة من حمض أو قاعدة، ويتكون غالبًا من حمض ضعيف وقاعدته المرافقة أو قاعدة ضعيفة وحمضها المرافق. تكون قدرته أفضل قرب pH = pKa، وتبلغ ذروتها تقريبًا عندما تتقارب كميتا المكوّنين."], ["المولارية|تركيز مولاري|المول لكل لتر|molarity", "المولارية M تساوي عدد مولات المذاب مقسومًا على حجم المحلول النهائي باللتر: M=n/V. لا يُستخدم حجم المذيب بدل حجم المحلول. عند التخفيف من دون فقد مادة مذابة، يمكن استخدام M₁V₁=M₂V₂ مع توحيد وحدات الحجم."], ["المتفاعل المحدد|المتفاعل الفائض|نسبة مولية|الحسابات الكيميائية|ستويكيومتري", "لتحديد المتفاعل المحدِّد: وازن المعادلة أولًا، وحوّل كميات المواد إلى مولات، ثم قارن n/المعامل الستوكيومتري لكل متفاعل. أصغر قيمة تحدد مقدار التفاعل النظري، ومنها تُحسب كمية الناتج والفائض المتبقي."], ["اتزان كيميائي|مبدأ لوشاتيليه|ثابت الاتزان|kc|kp", "عند الاتزان الديناميكي تتساوى سرعـتا التفاعل الأمامي والعكسي، وتبقى التراكيز ثابتة ما دامت الشروط ثابتة، لكنها ليست بالضرورة متساوية. يغير التركيز أو الضغط في الغازات موضع الاتزان وفق لوشاتيليه، بينما تغيّر درجة الحرارة قيمة ثابت الاتزان بحسب طبيعة التفاعل."], ["قانون بويل|قانون شارل|قانون غاي لوساك|قوانين الغازات|الغاز المثالي", "في الغاز المثالي مع ثبات كمية الغاز: قانون بويل PV ثابت عند ثبوت T، وقانون شارل V/T ثابت عند ثبوت P، وقانون غاي لوساك P/T ثابت عند ثبوت V. يجب استخدام درجة الحرارة بالكلفن، ويجمع القانون العام العلاقات في P₁V₁/T₁ = P₂V₂/T₂."], ["قانون نيوتن الثاني|القوة المحصلة|f=ma|تسارع جسم", "ينص قانون نيوتن الثاني على أن محصلة القوى تساوي معدل تغير كمية الحركة، وللكتلة الثابتة تكتب ΣF = ma. اتجاه التسارع هو اتجاه محصلة القوة، ووحدته m/s²، ويُشترط في التطبيق تحديد القوى والاتجاهات والكتلة بوحدات متسقة."], ["السرعة المتجهة|السرعة القياسية|التسارع|فرق السرعة", "السرعة القياسية هي المسافة المقطوعة لكل زمن، أما السرعة المتجهة فهي الإزاحة لكل زمن ولها اتجاه. التسارع هو تغير السرعة المتجهة مع الزمن؛ يمكن أن يتسارع جسم لأن مقدار سرعته أو اتجاهها أو كليهما يتغير."], ["قانون اوم|قانون أوم|v=ir|مقاومة كهربائية", "قانون أوم للعناصر الأومية عند ثبات الظروف الفيزيائية هو V=IR، حيث V فرق الجهد بالفولت، وI التيار بالأمبير، وR المقاومة بالأوم. لا يُفترض انطباقه خطيًا على كل عنصر في كل الظروف، مثل بعض الثنائيات والمصابيح المتغيرة الحرارة."], ["الخلية الجلفانية|الخلية الفولتية|خلية جلفانية|التحليل الكهربائي|الخلية الالكتروليتية", "الأكسدة دائمًا عند المصعد والاختزال دائمًا عند المهبط. الخلية الجلفانية تستثمر تفاعلًا تلقائيًا لتوليد طاقة كهربائية، أما خلية التحليل الكهربائي فتستخدم مصدرًا كهربائيًا لدفع تفاعل غير تلقائي. تتحدد إشارة كل قطب بحسب نوع الخلية."], ["عدسة محدبة|عدسة مقعرة|العدسة المحدبة|العدسة المقعرة|معادلة العدسة|البعد البؤري", "العدسة المحدبة تجمع الأشعة المتوازية تقريبًا نحو بؤرة، والعدسة المقعرة تفرقها كما لو خرجت من بؤرة افتراضية. للعدسة الرقيقة 1/f = 1/dₒ + 1/dᵢ وفق اصطلاح إشارات محدد؛ تحديد طبيعة الصورة يتطلب موضع الجسم ونوع العدسة واصطلاح الإشارات."], ["الانعكاس|قانون الانعكاس", "قانون الانعكاس: زاوية السقوط تساوي زاوية الانعكاس، وتقاس الزاويتان من العمود المقام على السطح لا من سطح المرآة. الشعاع الساقط والعمود والشعاع المنعكس تقع في مستوى واحد في النموذج الهندسي المعتاد."], ["انكسار الضوء|قانون سنيل|معامل الانكسار|الانعكاس الكلي الداخلي", "ينحرف الضوء عند انتقاله بين وسطين مختلفي معامل الانكسار بسبب تغير سرعته. يربط قانون سنيل n₁ sinθ₁ = n₂ sinθ₂ الزوايا المقاسة من العمود المقام. عند الانتقال من وسط أعلى معامل انكسار إلى أقل منه قد يحدث انعكاس كلي داخلي إذا تجاوزت زاوية السقوط الزاوية الحرجة."], ["قوة المجهر|تكبير المجهر|المجهر الضوئي|العدسة العينية", "في المجهر الضوئي المركب يصنع الجسم صورة مكبرة أولية بالعدسة الشيئية ثم تكبرها العدسة العينية. القدرة الكلية للتكبير في التقريب المعتاد تساوي تكبير الشيئية × تكبير العينية؛ زيادة التكبير وحدها لا تضمن زيادة الدقة، فالدقة تتأثر بالطول الموجي والفتحة العددية والتركيز والإضاءة."], ["الخاصية الاسموزية|التناضح|الاسموزية|غشاء شبه منفذ", "الأسموزية هي انتقال الماء عبر غشاء شبه منفذ استجابة لفارق الجهد المائي، ويُوصف غالبًا بأنه ينتقل من المحلول الأقل تركيزًا بالمذاب الفعال إلى الأعلى تركيزًا به عندما تكون بقية الشروط مناسبة. اتجاه الحركة يعتمد على نفاذية الغشاء والمواد المذابة، لا على حجم الخلية فقط."], ["البناء الضوئي|التمثيل الضوئي|معادلة البناء الضوئي", "يحوّل البناء الضوئي الطاقة الضوئية إلى طاقة كيميائية؛ في المعادلة الإجمالية المبسطة يُستخدم CO₂ والماء لتكوين سكريات وينطلق O₂. تعتمد السرعة على شدة الضوء وتركيز CO₂ ودرجة الحرارة وعوامل أخرى، ويصبح العامل الأقل ملاءمة محددًا للسرعة ضمن المجال المدروس."], ["التنفس الخلوي|دورة كربس|atp|سلسلة نقل الالكترونات", "التنفس الخلوي يحوّل الطاقة الكيميائية في المواد العضوية إلى ATP عبر التحلل السكري ومراحل لاحقة. في التنفس الهوائي يعمل الأكسجين مستقبلًا نهائيًا للإلكترونات في سلسلة النقل؛ يتغير مردود ATP حسب الكائن والظروف وطريقة الحساب المعتمدة."], ["انقسام متساوي|الانقسام المتساوي|انقسام منصف|الانقسام المنصف", "الانقسام المتساوي ينتج عادة خليتين بنتين لهما عدد الكروموسومات نفسه ويساعد في النمو وتعويض الخلايا. الانقسام المنصف يخفض عدد الكروموسومات إلى النصف لتكوين خلايا تناسلية، وتزيد عملية العبور والتوزيع المستقل التنوع الوراثي."], ["dna|الحمض النووي|الجين|الوراثة|الكروموسوم", "DNA جزيء يخزن المعلومات الوراثية في تسلسل النيوكليوتيدات. الجين جزء من DNA له وظيفة وظيفية أو تنظيمية، والكروموسوم بنية منظمة من DNA وبروتينات. النمط الظاهري ينتج من تفاعل الجينات والبيئة، وليس كل صفة تتحكم فيها جينة واحدة فقط."], ["السلسلة الغذائية|الشبكة الغذائية|المستهلكات|المحللات|هرم الطاقة", "تصف السلسلة الغذائية انتقال المادة والطاقة بين الكائنات، وتوضح الشبكة الغذائية العلاقات المتعددة داخل النظام البيئي. تنتقل نسبة من الطاقة إلى المستوى التالي وتفقد كمية كبيرة كحرارة وأيض، لذلك تقل الطاقة المتاحة عادة كلما صعدنا المستويات الغذائية."], ["الصفائح التكتونية|حركة الصفائح|الزلازل|البراكين", "ترتبط حركة الصفائح التكتونية بتباعد الصفائح وتقاربها وانزلاقها الجانبي. تتركز زلازل وبراكين كثيرة قرب الحدود، لكن أنماطها تعتمد على نوع الحدود والظروف الجيولوجية؛ لا تحدث البراكين عند كل حد صفائحي ولا تحدث كل الزلازل بسبب البراكين."], ["تغير المناخ|الاحتباس الحراري|غازات الدفيئة", "تُمتص بعض الأشعة تحت الحمراء المنبعثة من سطح الأرض وتُعاد إشعاعاتها بواسطة غازات الدفيئة، ما يرفع متوسط حرارة السطح مقارنة بما ستكون عليه دون هذا التأثير الطبيعي. زيادة تركيز غازات الدفيئة الناتجة عن النشاط البشري تعزز الاحترار وتؤثر في أنماط الطقس ومستوى البحر والنظم البيئية."], ["المنهج العلمي|المتغير المستقل|المتغير التابع|العوامل الثابتة|فرضية علمية", "في التجربة المضبوطة يغيّر الباحث المتغير المستقل، ويقيس أثره على المتغير التابع، ويحافظ على بقية العوامل المهمة ثابتة قدر الإمكان. الفرضية تفسير قابل للاختبار والتفنيد، وتساعد المكررات وضبط القياس ومقارنة النتائج على تقليل أثر الخطأ العشوائي."], ["الكثافة|حساب الكثافة", "الكثافة تساوي الكتلة مقسومة على الحجم: ρ=m/V. يجب أن تكون الوحدات متسقة؛ مثل kg/m³ أو g/cm³. الجسم يغوص أو يطفو بحسب مقارنة كثافته المتوسطة بكثافة السائل مع مراعاة قوة الطفو والشكل وحجم السائل المزاح."], ["قوة الطفو|مبدأ ارخميدس|أرخميدس|يطفو أم يغرق", "وفق مبدأ أرخميدس، قوة الطفو تساوي وزن السائل المزاح. الجسم الطافي في اتزان تكون قوة الطفو مساوية لوزنه، أما الجسم المغمور كليًا فتتحدد قوة الطفو بكثافة السائل وحجم الجزء المغمور وتسارع الجاذبية."], ["درجة الغليان|الغليان|ضغط البخار", "يغلي السائل عندما يتساوى ضغط بخاره مع الضغط الخارجي. لذلك تنخفض درجة الغليان عادة عند خفض الضغط وتزداد عند رفعه. وجود مذاب غير متطاير قد يرفع درجة الغليان، ويتأثر ذلك بتركيز الجسيمات الذائبة وبطبيعة النظام."], ["قانون حفظ الكتلة|موازنة المعادلة|وزن المعادلة الكيميائية", "في التفاعل الكيميائي المعتاد تُحفظ ذرات كل عنصر والكتلة الكلية في نظام مغلق؛ لذلك نوازن المعادلة بتغيير المعاملات أمام الصيغ لا بتغيير الأرقام السفلية للصيغ. التوازن في المعادلة يحافظ على نوع الذرات وعددها."]]);
